    ArtifactCapability, ArtifactCapabilityKind, ArtifactDeclaration, ArtifactDefinition, ArtifactDefinitionError, ArtifactExecutableIdentity, ArtifactIdentity, ArtifactIdentityClaim, ArtifactIdentityNamespace, ArtifactKindSpec, ArtifactLocale,
    PluginAssemblyError,
};
use semio_framework_value_derive as value_derive;
use std::collections::{BTreeMap, BTreeSet};

#[path = "🪜️definition-hierarchy/🦀️.rs"]
pub mod definition_hierarchy;
use definition_hierarchy::StdioArtifactDefinition;

#[path = "../🦀️.rs"]
pub mod registry;

#[path = "✏️editing/🦀️.rs"]
pub mod editing;
/// 🎬️ Bounded live-media exporters shared by retained Stdio artifact apps.
#[path = "🎬️media-export/🦀️.rs"]
pub mod media_export;
/// 📐️ The canonical ISO 10303-21 codec every STEP-family artifact shares.
#[path = "📐️part21/🦀️.rs"]
pub mod part21;

//#region 🧾️PayloadWire
/// 🧾️ Builds the operation of semantic kind `kind` from its leaf wire payload — JSON text in the exact `payload_value()`
/// shape — through the derive-generated [`kernel::Mutation::from_payload_value`]: the one decoder a wire-form `🥒️.feature`
/// row goes through, so no case adapter maps parameters onto an operation by hand. An artifact crate re-exports it for the
/// adapters that link only that crate.
pub fn mutation_from_payload_json<P, M: kernel::Mutation<P>>(kind: &str, payload: &str) -> Result<M, String> {
    let value = semio_framework_pack_json::parse(payload, semio_framework_pack_json::JsonMemberPolicy::Reject).map_err(|error| format!("{kind} payload is not JSON: {error}"))?;
    M::from_payload_value(kind, semio_framework_pack_json::to_dsl_value(&value)).map_err(|error| format!("{kind} payload does not decode: {error}"))
}

/// 🧾️ The leaf wire payload of `operation` as JSON text — the derive-generated [`kernel::Mutation::payload_value`] the
/// decoder above reads back, so a case adapter can hold a row's `params` against what the subject itself would emit.
pub fn mutation_payload_json<P, M: kernel::Mutation<P>>(operation: &M) -> String {
    semio_framework_pack_json::to_json_string(&operation.payload_value())
}

/// 🚫️ An operation dispatch refused: the outcome's first message, by its frozen `mutation.*` code and its sentence.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MutationRefusal {
    pub code: String,
    pub message: String,
}

impl std::fmt::Display for MutationRefusal {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(formatter, "[{}] {}", self.code, self.message)
    }
}

impl From<MutationRefusal> for String {
    fn from(refusal: MutationRefusal) -> String {
        refusal.to_string()
    }
}

/// ▶️ Applies `operation` to `snapshot` through its own diff and refuses — leaving `snapshot` untouched — when the
/// outcome carries a message, so a case adapter sees a rejection, by code, instead of encoding an unchanged model.
pub fn apply_mutation_checked<P, M: kernel::Mutation<P>>(snapshot: &mut P, operation: &M) -> Result<(), MutationRefusal> {
    let outcome = operation.diff(snapshot);
    if let Some(message) = outcome.messages().first() {
        return Err(MutationRefusal { code: message.code.0.to_string(), message: message.message.to_string() });
    }
    *snapshot = kernel::apply_diff(outcome.diff(), snapshot).map_err(|error| MutationRefusal { code: error.code.to_string(), message: error.message.to_string() })?;
    Ok(())
}

/// ↩️ [`kernel::Mutation::inverse`] against `base`, reachable from a crate that cannot name the kernel trait — the
/// production inverse itself, never a copy of its rules.
pub fn mutation_inverse<P, M: kernel::Mutation<P>>(operation: &M, base: &P) -> Result<Vec<M>, semio_framework_value::ValueError> {
    Ok({ operation.inverse(base)? })
}
//#endregion 🧾️PayloadWire

//#region 🪆️DoubleOption
/// 🪆️ Decodes a PRESENT key of an `Option<Option<T>>` field as `Some(inner)`, so a present `null` is `Some(None)` (cleared,
/// removed, valueless) and only an absent key (the field's bare `#[value(default)]`) is `None` (untouched): the value derive's
/// blanket `Option<T>` impl reads `Null` as absence at any depth and would collapse both. Paired with
/// `skip_serializing_if = "Option::is_none"`, `payload_value()` and `with_payload_value()` round-trip — the
/// `deserialize_double_option` shape the value derive's own docs name (`🧰️framework/🔨️modules/🌱️value/✨️derive`).
pub fn deserialize_double_option<T: semio_framework_value::FromValue>(value: semio_framework_value::DslValue) -> Result<Option<Option<T>>, semio_framework_value::ValueError> {
    <Option<T> as semio_framework_value::FromValue>::from_value(value).map(Some)
}
//#endregion 🪆️DoubleOption

/// 📚️ The `s.stdio.registry` shared schema documents: contracts several stdio artifacts `$ref` that no single artifact
/// owns — `$defs/SnapshotPatch` of every `patch-snapshot` leaf. Every package that runs those artifacts' editors declares
/// them (`PluginBuilder::schema_documents`: `stdio` itself and its `stdio-image`/`stdio-media` hosts), so the runtime
/// input reader (`registered_input_schema_document`) resolves them.
pub const STDIO_REGISTRY_SCHEMA_DOCUMENTS: semio_framework_schema_registry::ScopeSchemaExports = semio_framework_schema_registry::ScopeSchemaExports {
    scope: "s.stdio.registry",
    exports: &[semio_framework_schema_registry::SchemaExport { id: "schema", leaves: semio_framework_schema_registry::FacetLeaves { rust: "", typescript: "", graphql: "", json_schema: include_str!("../🧬️schema/🔣️.json"), proto: "" } }],
};

/// 🧩 One schema definition paired with its optional executable declaration.
pub enum ArtifactAssembly {
    Definition(ArtifactDefinition),
    Runtime(Box<ArtifactDeclaration>),
}

impl ArtifactAssembly {
    /// 🧾 Borrows the schema definition represented by this assembly.
    pub fn definition(&self) -> &ArtifactDefinition {
        match self {
            Self::Definition(definition) => definition,
            Self::Runtime(declaration) => declaration.definition(),
        }
    }
}

/// ⚙️ One schema capability bound to its artifact-owned executable address.
pub struct ArtifactExecutable {
    pub identity: String,
    pub executable: ArtifactExecutableIdentity,
}

impl ArtifactExecutable {
    /// 🧷 Captures a typed artifact executable without exporting its implementation type.
    pub fn from_function_pointer(identity: impl Into<String>, function: *const ()) -> Self {
        Self { identity: identity.into(), executable: ArtifactExecutableIdentity::from_function_pointer(function) }
    }
}

/// 🏭 One artifact-owned native document codec constructor.
#[derive(Clone, Copy)]
pub struct NativeCodecFactory {
    pub id: &'static str,
    pub artifact: &'static str,
    pub kind: fn() -> ArtifactKindSpec,
    pub codec: fn() -> kernel::ArtifactCodec,
}

/// 🪢 One verified native codec factory bound to schema and component identities.
#[derive(Clone)]
pub struct NativeCodecFactoryReceipt {
    pub plugin_id: &'static str,
    pub package_id: String,
    pub package_version: &'static str,
    pub factory_id: String,
    pub descriptor_codec_id: String,
    pub runtime_capability_id: String,
    pub artifact_kind: String,
    pub schema: String,
    pub pack_schema_hash: [u8; 32],
    pub extension: String,
    pub factory: fn() -> kernel::ArtifactCodec,
}

impl NativeCodecFactoryReceipt {
    /// 🔐 Rechecks the immutable factory result before a loader can bind it.
    pub fn instantiate(&self) -> Result<kernel::ArtifactCodec, PluginAssemblyError> {
        let codec = (self.factory)();
        if self.plugin_id.is_empty()
            || self.package_id.is_empty()
            || self.package_version.is_empty()
            || codec.schema != self.schema
            || codec.extension != self.extension
            || codec.pack_schema_hash != self.pack_schema_hash
            || codec.pack_schema_hash == [0; 32]
        {
            return Err(failure(format!("native codec receipt {} failed factory verification", self.artifact_kind)));
        }
        Ok(codec)
    }
}

/// 📦 Artifact-owned functions consumed by a selected component catalog.
#[derive(Clone, Copy)]
pub struct ArtifactContribution {
    pub identity: &'static str,
    pub schema: &'static str,
    pub definition_constraint: Option<&'static str>,
    pub definition: fn() -> Result<ArtifactDefinition, PluginAssemblyError>,
    pub assembly: fn() -> Result<ArtifactAssembly, PluginAssemblyError>,
    pub formats: fn() -> Result<Vec<FormatDescriptor>, ArtifactDefinitionError>,
    pub native_codecs: fn() -> Vec<NativeCodecFactory>,
}

/// 🛂 Validates an explicitly authored owner constraint without artifact-specific branches.
pub fn validate_definition_constraint(schema: &str, constraint: &str) -> Result<(), PluginAssemblyError> {
    let validator = semio_framework_schema::OwnedJsonSchemaValidator::compile(constraint).map_err(|error| failure(format!("invalid owned definition constraint: {error}")))?;
    validator.validate_json(schema).map_err(|error| failure(format!("owned definition constraint refused contribution: {error}")))?;
    Ok(())
}

/// 📊 Category counts keep declaration, registration, implementation, and verification distinct.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct CapabilityCounts {
    pub codecs: usize,
    pub mutations: usize,
    pub inferences: usize,
}

/// 📒 Honest capability status ledger for one or more artifact schemas.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct CapabilityLedger {
    pub declared: CapabilityCounts,
    pub registered: CapabilityCounts,
    pub implemented: CapabilityCounts,
    pub verified: CapabilityCounts,
}

impl CapabilityLedger {
    /// ➕ Adds an independently validated artifact ledger.
    pub fn include(&mut self, other: Self) {
        self.declared.codecs += other.declared.codecs;
        self.declared.mutations += other.declared.mutations;
        self.declared.inferences += other.declared.inferences;
        self.registered.codecs += other.registered.codecs;
        self.registered.mutations += other.registered.mutations;
        self.registered.inferences += other.registered.inferences;
        self.implemented.codecs += other.implemented.codecs;
        self.implemented.mutations += other.implemented.mutations;
        self.implemented.inferences += other.implemented.inferences;
        self.verified.codecs += other.verified.codecs;
        self.verified.mutations += other.verified.mutations;
        self.verified.inferences += other.verified.inferences;
    }
}

